SELECT tm.level_val, MIN(tm.score_val), MAX(tm.score_val), AVG(tm.score_val) 
FROM transplant_matching tm 
GROUP BY tm.level_val;

SELECT DISTINCT LOWER(ar.exp_rev_notes) 
FROM transplant_matching tm 
JOIN administrative_and_review ar ON tm.match_rec_registry = ar.adm_rev_registry;

SELECT COUNT(*) FROM transplant_matching tm 
JOIN administrative_and_review ar ON tm.match_rec_registry = ar.adm_rev_registry
WHERE tm.level_val = 'Marginal' AND (ar.exp_rev_notes IS NULL OR LOWER(ar.exp_rev_notes) = 'none');

SELECT COUNT(*) FROM transplant_matching tm 
JOIN clinical c ON tm.recip_ref_reg = c.clin_recip_registry
WHERE tm.level_val = 'Marginal';

SELECT COUNT(*) FROM transplant_matching tm 
LEFT JOIN clinical c ON tm.recip_ref_reg = c.clin_recip_registry
WHERE tm.level_val = 'Marginal' AND c.clin_recip_registry IS NOT NULL;

